<?php namespace Tests\Feature;use App\Enums\OrderStatus;use App\Models\{Order,OrderItem,Payout,Seller,SellerOrder,User};use App\Services\SellerWalletService;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class PhaseFourWalletPayoutTest extends TestCase{use RefreshDatabase;public function test_completed_order_credits_once_and_payout_reserves_then_releases():void{$u=User::factory()->create(['role'=>'seller','status'=>'active']);$s=Seller::create(['user_id'=>$u->id,'name'=>'S','slug'=>'s','status'=>'approved','commission_bps'=>0]);$o=Order::create(['order_number'=>'W1','reference'=>'W1','buyer_id'=>User::factory()->create()->id,'status'=>'COMPLETED','payment_method'=>'cod','payment_status'=>'PAID','subtotal'=>100,'shipping_fee'=>50,'discount_amount'=>0,'total_amount'=>150,'total_minor'=>15000,'recipient_name'=>'x','recipient_phone'=>'x','province'=>'x','municipality'=>'x','barangay'=>'x','street_address'=>'x','shipping_address'=>[]]);$so=SellerOrder::create(['order_id'=>$o->id,'seller_id'=>$s->id,'subtotal_minor'=>10000,'shipping_fee_minor'=>5000,'commission_minor'=>1000,'status'=>'completed','workflow_status'=>OrderStatus::Completed]);OrderItem::create(['order_id'=>$o->id,'seller_order_id'=>$so->id,'seller_id'=>$u->id,'product_slug'=>'wallet-item','product_name'=>'x','quantity'=>1,'unit_price_minor'=>10000,'unit_price'=>100,'line_total'=>100,'commission_minor'=>1000]);$w=app(SellerWalletService::class);$w->creditCompleted($so);$w->creditCompleted($so);$this->assertSame(9000,$w->summary($s)['available_minor']);$p=$w->request($s,5000);$this->assertSame(4000,$w->summary($s)['available_minor']);$admin=User::factory()->create(['role'=>'admin','status'=>'active']);$w->review($p,$admin,'REJECTED','No');$this->assertSame(9000,$w->summary($s)['available_minor']);}}
